import type { PublicQuestion } from "./types";

// PROMPTS ONLY — no answers. Safe to ship to the browser. Generated from
// lib/questions.server.ts by scripts/gen-public-questions.ts — do not edit by hand.
export const PUBLIC_QUESTIONS: PublicQuestion[] = [
  { id: "bbq-1", type: "text", category: "bbq", body: "At long last, it's finally time to get cooking. You've gotten to know your smoker and you've sourced or seasoned the best wood you can possibly find." },
  { id: "bbq-2", type: "text", category: "bbq", body: "Life is too short for bad BBQ!" },
  { id: "bbq-3", type: "text", category: "bbq", body: "I tell people I'm living the dream, because I've turned my hobby into a job." },
  { id: "bbq-4", type: "text", category: "bbq", body: "Didn't have great equipment or great knowledge, but the passion was there. That's never changed." },
  { id: "bbq-5", type: "text", category: "bbq", body: "it's all about cooking delicious food and taking pride in everything we cook" },
  { id: "bbq-6", type: "text", category: "bbq", body: "But the fact that in Texas barbecue, you're taking one of the worst pieces of the animal and converting it into one of the best is a miracle itself." },
  { id: "bbq-7", type: "text", category: "bbq", body: "Sure, I was poor. But barbecue has never been a rich man's pleasure. It's always been a culture of thrift." },
  { id: "bbq-8", type: "text", category: "bbq", body: "I think it's key that you buy the best thing that you can afford." },
  { id: "bbq-9", type: "text", category: "bbq", body: "You learn from your mistakes and you just keep going and trying to do the best you can." },
  { id: "bbq-10", type: "text", category: "bbq", body: "A little beef tallow on the cutting board makes for those sexy slices." },
  { id: "bbq-11", type: "text", category: "bbq", body: "I am an absolute insatiable learner. I love to learn more than anything in the world." },
  { id: "bbq-12", type: "text", category: "bbq", body: "There is a saying in my industry, you buy the meat, not the sauce." },
  { id: "bbq-13", type: "text", category: "bbq", body: "I've always looked at myself as a student of BBQ, because no matter how long you've been doing it, there's always something else to learn." },
  { id: "bbq-14", type: "text", category: "bbq", body: "You can't make a fake fire." },
  { id: "bbq-15", type: "text", category: "bbq", body: "If the temperatures are up and down, it's pretty likely that your firewood is too big, so it's robbing energy from the fire to get to a combustion point." },
  { id: "bbq-16", type: "text", category: "bbq", body: "The worst thing you can do is overcook it." },
  { id: "bbq-17", type: "text", category: "bbq", body: "Like Traeger, I subscribe to the all-natural BBQ philosophy. The hardwood taste and authentic flavors from Traeger's wood fire and wood pellets just can't be beat." },
  { id: "bbq-18", type: "text", category: "bbq", body: "Barbecue feeds your soul because it brings people together." },
  { id: "bbq-19", type: "text", category: "bbq", body: "I do not say I'm lucky. I work too hard to be lucky." },
  { id: "bbq-20", type: "text", category: "bbq", body: "I'd be setting alarms and waking up every 30 minutes; go put a couple logs on the fire, and eventually, it became a business." },
  { id: "bbq-21", type: "text", category: "bbq", body: "Brisket doesn’t care about your schedule, and that’s the first lesson. Trim it clean, season it honest, and let the smoke do its slow little sermon." },
  { id: "bbq-22", type: "text", category: "bbq", body: "Smoke rings are pretty, but flavor pays the rent. If your bark has pepper bite, fat shimmer, and that campfire depth, nobody’s asking for a microscope." },
  { id: "bbq-23", type: "text", category: "bbq", body: "A pork shoulder is basically a trust exercise wrapped in butcher paper. Somewhere around hour six, it looks like nothing is happening, which means everything is happening." },
  { id: "bbq-24", type: "text", category: "bbq", body: "Don’t drown good meat in rub until it tastes like a spice cabinet fell down the stairs. Salt, pepper, heat, smoke, and restraint will get you invited back." },
  { id: "bbq-25", type: "text", category: "bbq", body: "Burgers need confidence, not choreography. Hot grate, cold meat, one good flip, and cheese melted just enough to start looking dangerous." },
  { id: "bbq-26", type: "text", category: "bbq", body: "I like ribs with a little tug, not falling off the bone like they gave up on themselves. Sauce goes on near the end, just enough to shine them up for company." },
  { id: "bbq-27", type: "text", category: "bbq", body: "The secret to good chicken thighs is patience and not poking at them every twelve seconds like a raccoon with a badge. Let the skin render, let the edges crisp, then bring in the glaze." },
  { id: "bbq-28", type: "text", category: "bbq", body: "I build my fire before I build my menu. Oak for beef, apple for pork, and a little hickory when I want the backyard to smell like it has opinions." },
  { id: "bbq-29", type: "text", category: "bbq", body: "If you’re looking at your watch, you’re doing it all wrong. Real Texas brisket doesn't care about your schedule, it only cares about the wood, the smoke, and the internal temp. Pull it when it jiggles like Jell-O and let it rest for at least two hours, period." },
  { id: "bbq-30", type: "text", category: "bbq", body: "That bark right there isn't burnt, it’s pure flavor built up over twelve hours of post oak smoke. The secret is keeping the fire clean and the rub heavy on the coarse black pepper. Slice it thick and let the juice do the talking." },
  { id: "bbq-31", type: "text", category: "bbq", body: "Look at that smoke ring definition on these pork ribs. They’ve got just enough bite to come clean off the bone without falling apart into mush. Hit 'em with a light glaze of sweet heat right at the end for that picture-perfect shine." },
  { id: "bbq-32", type: "text", category: "bbq", body: "Sunday mornings start at 4:00 AM around here, getting the firebox stoked and the ambient temp locked right at 225. There’s something peaceful about watching the smoke roll while the rest of the neighborhood is still asleep. Grab a coffee, it's gonna be a long, beautiful day." },
  { id: "bbq-33", type: "text", category: "bbq", body: "A lot of guys overcomplicate the rub, but honestly, kosher salt and cracked pepper are all a good piece of beef needs. Let the quality of the meat and the draft of your offset smoker do the heavy lifting. If the smoke is blue, you’re doing it right." },
  { id: "bbq-34", type: "text", category: "bbq", body: "We are officially locked and loaded for the weekend crowd, and these pork shoulders are already looking incredible. The fat cap is rendering down perfectly, basting the meat from the inside out. Get down here before the sold-out sign goes up." },
  { id: "bbq-35", type: "text", category: "bbq", body: "Tinfoil is a crutch, but peach butcher paper is a pitmaster's best friend. It breathes just enough to keep your crust nice and crunchy while holding in those essential juices. Trust the process and don't rush the wrap." },
  { id: "bbq-36", type: "text", category: "bbq", body: "You can buy the most expensive rig on the market, but you can’t buy patience. True barbecue is an art form of minor adjustments, feeling the heat, and listening to the sizzle on the deflector plate. Fire up the pits and let’s get to work." },
  { id: "bbq-37", type: "text", category: "bbq", body: "In today's world, barbecue is more than just cooking meat over fire. It is a journey that brings people together and nourishes the soul, one tender bite at a time." },
  { id: "bbq-38", type: "text", category: "bbq", body: "Great brisket isn't just about heat; it's about patience, respect, and an unwavering devotion to the craft." },
  { id: "bbq-39", type: "text", category: "bbq", body: "What separates a good pitmaster from a great one? The answer is simple: an unrelenting commitment to the fire." },
  { id: "bbq-40", type: "text", category: "bbq", body: "At the end of the day, smoking meat is about more than flavor. It's about connection, tradition, and the stories we share around the table." },
  { id: "business-1", type: "text", category: "business", body: "Discipline equals freedom." },
  { id: "business-2", type: "text", category: "business", body: "It's not what you preach, it's what you tolerate." },
  { id: "business-3", type: "text", category: "business", body: "There are no bad teams, only bad leaders." },
  { id: "business-4", type: "text", category: "business", body: "When setting expectations, no matter what has been said or written, if substandard performance is accepted and no one is held accountable—if there are no consequences—that poor performance becomes the new standard." },
  { id: "business-5", type: "text", category: "business", body: "Good is the enemy of great. And that is one of the key reasons why we have so little that becomes great." },
  { id: "business-6", type: "text", category: "business", body: "Greatness is not a function of circumstance. Greatness, it turns out, is largely a matter of conscious choice, and discipline." },
  { id: "business-7", type: "text", category: "business", body: "Great vision without great people is irrelevant." },
  { id: "business-8", type: "text", category: "business", body: "You can make more friends in two months by becoming interested in other people than you can in two years by trying to get other people interested in you." },
  { id: "business-9", type: "text", category: "business", body: "Most people do not listen with the intent to understand; they listen with the intent to reply." },
  { id: "business-10", type: "text", category: "business", body: "People don't buy what you do; they buy why you do it." },
  { id: "business-11", type: "text", category: "business", body: "When it comes to standards, as a leader, it's not what you preach, it's what you tolerate." },
  { id: "business-12", type: "text", category: "business", body: "Good is the enemy of great." },
  { id: "business-13", type: "text", category: "business", body: "True operational scale isn’t about working harder; it’s about decoupling your revenue growth from your headcount. When leaders focus on building repeatable frameworks rather than firefighting daily anomalies, the entire organization aligns. Focus on systems that empower autonomy, not bottlenecks that require permission." },
  { id: "business-14", type: "text", category: "business", body: "The market doesn’t care about your legacy strategy or how successful your previous product launch was. Disruption happens when an organization becomes too comfortable protecting past wins instead of cannibalizing its own business model to innovate. Stay paranoid, stay curious, and keep executing." },
  { id: "business-15", type: "text", category: "business", body: "Resilience isn't an innate personality trait; it’s an organizational muscle developed through navigating ambiguity. When milestones are missed, the instinct is often to assign blame, but the highest-performing cultures treat failures as data points for iterative improvement. Turn your post-mortems into launchpads." },
  { id: "business-16", type: "text", category: "business", body: "Empathy is often dismissed as a soft skill, but it is actually the hardest and most lucrative tool in a modern executive's toolkit. When employees feel genuinely understood and psychologically safe, retention skyrocketing follows naturally. Take care of your people, and they will relentlessly take care of your metrics." },
  { id: "business-17", type: "text", category: "business", body: "True leadership isn't validated by how many decisions you make, but by how many leaders you develop to make them instead. If your department paralyzes the moment you go on vacation, you haven’t built a team, you’ve built a dependency. Step back so your people can step up." },
  { id: "business-18", type: "text", category: "business", body: "We often mistake frantic activity for progress, but velocity without a clear direction is just noise. The best executives I’ve worked with spend more time listening to frontline friction than reviewing high-level slide decks. If you want to fix your culture, start by fixing the small things that drain your team's daily energy." },
  { id: "business-19", type: "text", category: "business", body: "Good leaders do not remove all friction; they remove the useless friction. Some tension sharpens the work, but bureaucracy just puts a velvet rope around progress." },
  { id: "business-20", type: "text", category: "business", body: "Your calendar is a confession. It reveals what you reward, what you avoid, and what you are accidentally teaching everyone else to value." },
  { id: "business-21", type: "text", category: "business", body: "The mistake many teams make is confusing alignment with agreement. Alignment means we know the decision, the tradeoff, and the owner, even if we would have chosen differently." },
  { id: "business-22", type: "text", category: "business", body: "Culture is not what gets printed on the wall; it is what people feel safe saying in the meeting. The real work of leadership is lowering the cost of honesty." },
  { id: "business-23", type: "text", category: "business", body: "Trust compounds slowly and spends quickly. Every missed follow-through is a small withdrawal, even when nobody says it out loud." },
  { id: "business-24", type: "text", category: "business", body: "A strategy that cannot survive contact with the frontline is not a strategy, it is office theater. The best leaders keep walking back to the people closest to the work." },
  { id: "disney-1", type: "text", category: "disney", body: "You have forgotten who you are and so have forgotten me. Look inside yourself, Simba. You are more than what you have become. You must take your place in the Circle of Life." },
  { id: "disney-2", type: "text", category: "disney", body: "Everything you see exists together in a delicate balance. As king, you need to understand that balance and respect all the creatures, from the crawling ant to the leaping antelope." },
  { id: "disney-3", type: "text", category: "disney", body: "Look, over in that house is a kid who thinks you are the greatest, and it's not because you're a Space Ranger, pal. It's because you're a toy. You are his toy." },
  { id: "disney-4", type: "text", category: "disney", body: "You are a sad, strange little man, and you have my pity. Farewell." },
  { id: "disney-5", type: "text", category: "disney", body: "Well, you can't never let anything happen to him. Then nothing would ever happen to him. Not much fun for little Harpo." },
  { id: "disney-6", type: "text", category: "disney", body: "If he could learn to love another and earn her love in return by the time the last petal fell, then the spell would be broken. If not, he would be doomed to remain a beast for all time." },
  { id: "disney-7", type: "text", category: "disney", body: "Dishonor! Dishonor on your whole family! Make a note of this: dishonor on you, dishonor on your cow!" },
  { id: "disney-8", type: "text", category: "disney", body: "The flower that blooms in adversity is the most rare and beautiful of all. You don't meet a girl like that every dynasty." },
  { id: "disney-9", type: "text", category: "disney", body: "Some people are worth melting for. Just maybe not right this second." },
  { id: "disney-10", type: "text", category: "disney", body: "Not everyone can become a great artist, but a great artist can come from anywhere. It is difficult to imagine more humble origins than those of the genius now cooking at Gusteau's." },
  { id: "disney-11", type: "text", category: "disney", body: "You made it! Go! Go save Riley! Take her to the moon for me… okay?" },
  { id: "disney-12", type: "text", category: "disney", body: "It's kind of fun to do the impossible." },
  { id: "disney-13", type: "text", category: "disney", body: "You see, a heart isn't judged by how much you love, but by how much you are loved by others in return. Even when the shadows grow long and the path ahead seems completely lost, that warmth will always show you the way home. Just take my hand and don't be afraid." },
  { id: "disney-14", type: "text", category: "disney", body: "It doesn't matter if you're made of tin, or wood, or fluff and stuffing, because real magic comes from what's beating inside your chest. When you love someone, you give them a piece of yourself that can never be broken or taken away. That's a promise that lasts forever." },
  { id: "disney-15", type: "text", category: "disney", body: "Change can be a little scary at first, kind of like stepping outside into a big, loud thunderstorm without an umbrella. But if we never let the rain fall, the flowers in the valley would never get a chance to grow. I think it’s time for us to see what’s waiting out there." },
  { id: "disney-16", type: "text", category: "disney", body: "They can take away our crowns, lock us in the highest towers, and banish us to the edge of the map, but they can never steal our dreams. As long as we have each other, we have a spark that can light up the darkest night. Now, let’s go show them what we're made of." },
  { id: "disney-17", type: "text", category: "disney", body: "The stars up there look so small, but I think they’re actually giant windows looking into all the places we haven't discovered yet. If we fly fast enough, maybe we can find a way right through them. We just have to hold on tight and never look down." },
  { id: "disney-18", type: "text", category: "disney", body: "Hurrying won't make the winter pass any faster, my little friend, as every single snowflake has its own special time to dance. Sit here by the hearth with me and let the frost paint its pictures on the windowpanes. Spring always knows exactly when to arrive." },
  { id: "disney-19", type: "text", category: "disney", body: "“Home isn’t the door,” the candle said, flickering proudly. “It’s who leaves a light on when you’re late.”" },
  { id: "disney-20", type: "text", category: "disney", body: "“The forest doesn’t give maps to people who already know everything,” the fox said. “It prefers the lost ones. They listen better.”" },
  { id: "disney-21", type: "text", category: "disney", body: "“Your song is still in there,” the whale murmured beneath the silver waves. “It just got buried under everyone else’s noise.”" },
  { id: "disney-22", type: "text", category: "disney", body: "“I’m not small,” said the mouse, adjusting his acorn helmet. “I’m travel-sized for destiny.”" },
  { id: "disney-23", type: "text", category: "disney", body: "“I tried to be perfect and accidentally became miserable,” said the little prince. “So tomorrow I’m going to be terrible at something and see if the sun still rises.”" },
  { id: "disney-24", type: "text", category: "disney", body: "Oh, great, another ancient, booby-trapped temple filled with spikes and bugs, because a regular walk in the woods would just be too boring. Don’t touch anything, especially not that giant, shiny ruby that is practically screaming 'grab me' right now. Wait, where did you go?" },
  { id: "speech-1", type: "text", category: "speech", body: "There are these two young fish swimming along and they happen to meet an older fish swimming the other way, who nods at them and says 'Morning, boys. How's the water?' And the two young fish swim on for a bit, and then eventually one of them looks over at the other and goes 'What the hell is water?'" },
  { id: "speech-2", type: "text", category: "speech", body: "The point of the fish story is merely that the most obvious, important realities are often the ones that are hardest to see and talk about." },
  { id: "speech-3", type: "text", category: "speech", body: "With your college diploma you now have a crushing advantage over 8% of the workforce. I'm talking about dropout losers like Bill Gates, Steve Jobs, and Mark Zuckerberg." },
  { id: "speech-4", type: "text", category: "speech", body: "I went from being in the center of the grid to not only off the grid, but underneath the coffee table that the grid sits on, lost in the shag carpeting that is underneath the coffee table supporting the grid." },
  { id: "speech-5", type: "text", category: "speech", body: "If you want to change the world, start off by making your bed." },
  { id: "speech-6", type: "text", category: "speech", body: "If you make your bed every morning you will have accomplished the first task of the day. It will give you a small sense of pride, and it will encourage you to do another task and another and another." },
  { id: "speech-7", type: "text", category: "speech", body: "Death is very likely the single best invention of Life. It is Life's change agent. It clears out the old to make way for the new." },
  { id: "speech-8", type: "text", category: "speech", body: "Stay Hungry. Stay Foolish." },
  { id: "speech-9", type: "text", category: "speech", body: "As you walk across this stage today, remember that your degree is not a final destination, but rather a key to doors you haven't even envisioned yet. The world doesn't need you to fit into the existing molds; it desperately needs you to shatter them and build something better. Go out there and make kindness your loudest attribute." },
  { id: "speech-10", type: "text", category: "speech", body: "We often spend our youth waiting for the perfect moment to start, waiting for a sign that we are finally ready to make our mark. The truth is, perfection is an illusion designed to keep you comfortable in the harbor of safety. Row away from the shore, embrace the storms, and realize you were ready all along." },
  { id: "speech-11", type: "text", category: "speech", body: "Look around this room at the people who supported you, wept with you, and pushed you to reach this milestone. No one achieves greatness in a vacuum, and our success is always a collective tapestry woven by those who believed in us. Carry their belief into the world and become that pillar for someone else." },
  { id: "speech-12", type: "text", category: "speech", body: "Do not let the fear of making a mistake paralyze your ambition, because every failure is simply a tuition payment toward your future wisdom. The most extraordinary lives are rarely linear; they are messy, unpredictable, and defined by the moments someone chose to get back up. Write a story worth telling." },
  { id: "speech-13", type: "text", category: "speech", body: "Your education has given you a voice, and with that voice comes the profound responsibility to speak for those who are currently unheard. Do not use your talents merely to climb the ladders of corporate success; use them to widen the base so more people can climb with you. True legacy is measured by what you give back." },
  { id: "speech-14", type: "text", category: "speech", body: "Today marks the end of a chapter, but the pen is now entirely in your hands for the rest of the book. Do not let the cynicism of the world dampen the fierce optimism that brought you to this very moment. Be bold, stay curious, and never apologize for dreaming too big." },
  { id: "speech-15", type: "text", category: "speech", body: "You are not here because the path was clear. You are here because you kept walking when the map turned into fog." },
  { id: "speech-16", type: "text", category: "speech", body: "Do not mistake certainty for wisdom. The people who change the world are often the ones willing to ask one more question when everyone else has packed up the chairs." },
];

export const PUBLIC_BY_ID: Record<string, PublicQuestion> = Object.fromEntries(
  PUBLIC_QUESTIONS.map((q) => [q.id, q]),
);
